// "How to make it" media for a curriculum sign, and the credit each piece
// needs. The table is generated by ml/scripts/export_reference_media.py (see
// public/reference/CREDITS.txt): ASL letters from the ASL Alphabet set
// (GPL 2), FSL words from FSL-105 (CC BY 4.0), ASL words from ASL Citizen,
// WLASL and MS-ASL. Those three are research-only licenses that don't allow
// showing the footage; the project owner chose to use them in this
// non-commercial capstone anyway. A sign with no entry falls back to
// SignReference's "no picture yet" state.
import table from "../data/referenceMedia.json";
import type { SignGroup, SignLanguage } from "./curriculum";

export type MediaCreditKey = "asl-alphabet" | "fsl-105" | "asl-citizen" | "wlasl" | "ms-asl";

export type SignMedia = {
  kind: "image" | "video";
  uri: string;
  credit: MediaCredit;
};

export type MediaCredit = {
  /** Short line shown under the media. */
  label: string;
  license: string;
  url: string;
};

export const MEDIA_CREDITS: Record<MediaCreditKey, MediaCredit> = {
  "asl-alphabet": {
    label: "Photo: ASL Alphabet dataset, Akash Nagaraj (2018)",
    license: "GPL 2",
    url: "https://www.kaggle.com/datasets/grassknoted/asl-alphabet",
  },
  "fsl-105": {
    label: "Video: FSL-105, Tupal / De La Salle University (2023)",
    license: "CC BY 4.0",
    url: "https://data.mendeley.com/datasets/48y2y99mb9/2",
  },
  "asl-citizen": {
    label: "Video: ASL Citizen, Desai et al. / Microsoft Research (2023)",
    license: "Microsoft Research License (research use)",
    url: "https://www.microsoft.com/en-us/research/project/asl-citizen/",
  },
  wlasl: {
    label: "Video: WLASL, Li et al. (2020)",
    license: "C-UDA (research use)",
    url: "https://dxli94.github.io/WLASL/",
  },
  "ms-asl": {
    label: "Video: MS-ASL, Vaezi Joze & Koller / Microsoft (2019)",
    license: "C-UDA (research use)",
    url: "https://www.microsoft.com/en-us/research/project/ms-asl/",
  },
};

type Entry = { type: "image" | "video"; uri: string; credit: MediaCreditKey };
const entries = table as Record<string, Entry>;

export function getSignMedia(language: SignLanguage, group: SignGroup, sign: string): SignMedia | null {
  const entry = entries[`${language}/${group}/${sign}`];
  if (!entry) return null;
  return { kind: entry.type, uri: entry.uri, credit: MEDIA_CREDITS[entry.credit] };
}

// A still photo can't show movement: J and Z are traced in the air, so the
// reference says so next to the handshape.
const MOTION_HINTS: Record<string, string> = {
  "asl/letters/J": "J moves: make this handshape, then draw a J in the air with your little finger.",
  "asl/letters/Z": "Z moves: point your index finger, then draw a Z in the air.",
};

export function getMotionHint(language: SignLanguage, group: SignGroup, sign: string): string | null {
  return MOTION_HINTS[`${language}/${group}/${sign}`] ?? null;
}
